def fit_knn_strategy(cases, k: int = 3):
    if not cases:
        return None
    keys = _numeric_keys(cases)
    rows = []
    for x, y in cases:
        rows.append(([float(x.get(key, 0.0)) for key in keys], y))
    return {'kind': 'KNN_STRATEGY', 'features': keys, 'rows': rows, 'k': max(1, int(k))}

def strategy_accuracy(model, cases):
    if not model or not cases:
        return 0.0
    return sum(knn_predict(model, x) == y for x, y in cases) / len(cases)

def select_knn_k(fit_cases, validation_cases, candidates=(1, 3, 5, 7, 9)):
    trials = []
    for k in candidates:
        model = fit_knn_strategy(fit_cases, k)
        acc = strategy_accuracy(model, validation_cases)
        trials.append((acc, -int(k), int(k), model))
    _, _, k, model = max(trials, key=lambda z: z[:2])
    return model, {'selected_k': k, 'validation': max(t[0] for t in trials), 'trials': [{'k': t[2], 'accuracy': t[0]} for t in trials]}

def create_app(system: Optional[UnifiedCognitiveSystem] = None) -> FastAPI:
    core = system or UnifiedCognitiveSystem(os.getenv("YADO_DB_PATH", "cognitive_system_v2.db"))
    app = FastAPI(title="YADO-CORE", version="2.0.0")
    app.state.core = core

    async def require_signed_request(
        request: Request,
        x_api_key_id: Optional[str] = Header(default=None),
        x_api_signature: Optional[str] = Header(default=None),
        x_api_timestamp: Optional[str] = Header(default=None),
    ) -> Dict[str, Any]:
        if not all([x_api_key_id, x_api_signature, x_api_timestamp]):
            raise HTTPException(status_code=401, detail="missing authentication headers")
        body = await request.body()
        target = request.url.path
        if request.url.query:
            target += "?" + request.url.query
        try:
            return core.verify_signature(
                key_id=x_api_key_id,
                signature=x_api_signature,
                timestamp=x_api_timestamp,
                method=request.method,
                path=target,
                body=body,
            )
        except ValueError as exc:
            raise HTTPException(status_code=401, detail=str(exc)) from exc

    @app.get("/")
    def index() -> Dict[str, Any]:
        return {"status": "YADO-CORE running", "version": "2.0.0"}

    @app.get("/health")
    def health() -> Dict[str, Any]:
        return {"status": "ok", "uptime_seconds": (utc_now() - core.start_time).total_seconds()}

    @app.get("/metrics")
    def metrics() -> Dict[str, Any]:
        return {
            **core.knowledge_metrics(),
            "goals": len(core.executive.goals),
            "capabilities": len(core.executive.capabilities),
            "uptime_seconds": (utc_now() - core.start_time).total_seconds(),
        }

    @app.post("/registration-token")
    def registration_token(authorization: Optional[str] = Header(default=None)) -> Dict[str, Any]:
        admin_token = os.getenv("YADO_ADMIN_TOKEN")
        if not admin_token:
            raise HTTPException(status_code=503, detail="YADO_ADMIN_TOKEN is not configured")
        supplied = authorization.removeprefix("Bearer ") if authorization else ""
        if not secrets.compare_digest(supplied, admin_token):
            raise HTTPException(status_code=401, detail="unauthorized")
        token, expires = core.generate_registration_token()
        return {"token": token, "expires": expires.isoformat()}

    @app.post("/register")
    def register(payload: Dict[str, Any]) -> Dict[str, Any]:
        result = core.register_point(str(payload.get("token", "")), payload.get("permissions"))
        if result.get("status") != "success":
            raise HTTPException(status_code=400, detail=result.get("message", "registration failed"))
        return result

    def require_permission(identity: Dict[str, Any], permission: str) -> None:
        permissions = set(identity.get("permissions", []))
        if permission not in permissions and "*" not in permissions:
            raise HTTPException(status_code=403, detail=f"missing permission: {permission}")

    @app.post("/resources")
    def add_resource(payload: ResourceIn, identity: Dict[str, Any] = Depends(require_signed_request)) -> Dict[str, Any]:
        require_permission(identity, "write")
        return core.add_resource(payload.resource_id, payload.text, payload.metadata, payload.tags, payload.seed)

    @app.get("/resources/{resource_id}")
    def get_resource(resource_id: str, identity: Dict[str, Any] = Depends(require_signed_request)) -> Dict[str, Any]:
        require_permission(identity, "read")
        found = core.get_resource(resource_id)
        if found is None:
            raise HTTPException(status_code=404, detail="resource not found")
        return found

    @app.get("/search")
    def search(q: str, k: int = 5, identity: Dict[str, Any] = Depends(require_signed_request)) -> Dict[str, Any]:
        require_permission(identity, "read")
        return {"results": core.find_concept_neighbors(q, max(1, min(k, 50)))}

    @app.post("/goals")
    def create_goal(payload: GoalIn, identity: Dict[str, Any] = Depends(require_signed_request)) -> Dict[str, Any]:
        require_permission(identity, "write")
        return asdict(core.executive.create_goal(payload.objective, payload.required_capabilities, payload.success_criteria))

    @app.post("/goals/{goal_id}/cycle")
    def run_cycle(goal_id: str, identity: Dict[str, Any] = Depends(require_signed_request)) -> Dict[str, Any]:
        require_permission(identity, "write")
        if goal_id not in core.executive.goals:
            raise HTTPException(status_code=404, detail="goal not found")
        return core.executive.run_cycle(goal_id)

    @app.post("/experiments/evaluate")
    def evaluate_experiment(payload: ExperimentIn, identity: Dict[str, Any] = Depends(require_signed_request)) -> Dict[str, Any]:
        require_permission(identity, "write")
        if payload.candidate_id not in core.executive.candidates:
            raise HTTPException(status_code=404, detail="candidate not found")
        receipt = core.executive.evaluate_candidate(
            payload.candidate_id,
            payload.baseline_score,
            payload.candidate_score,
            payload.ablation_score,
            payload.min_gain,
            payload.min_ablation_drop,
        )
        return asdict(receipt)

    return app

def _rebuild_index(self) -> None:
        if len(self.data_points) == 0:
            self.nn_index = None
            return
        self.nn_index = NearestNeighbors(metric="cosine", algorithm="brute")
        self.nn_index.fit(self.data_points)

def find_concept_neighbors(self, query: Union[str, np.ndarray], k: int = 5) -> List[Dict[str, Any]]:
        if self.nn_index is None or not self.resource_ids:
            return []
        if isinstance(query, str):
            vector = self.embedder.encode(query)
        else:
            vector = np.asarray(query, dtype=np.float32)
            if vector.shape != (self.embedder.dimension,):
                raise ValueError(f"query vector must have shape ({self.embedder.dimension},)")
        distances, indices = self.nn_index.kneighbors(vector.reshape(1, -1), n_neighbors=min(k, len(self.resource_ids)))
        results: List[Dict[str, Any]] = []
        for distance, idx in zip(distances[0], indices[0]):
            resource_id = self.resource_ids[int(idx)]
            node = self.graph.nodes[resource_id]
            results.append(
                {
                    "resource_id": resource_id,
                    "similarity": float(1.0 - distance),
                    "metadata": dict(node.get("metadata", {})),
                    "tags": list(node.get("tags", [])),
                }
            )
        return results

def search(q: str, k: int = 5, identity: Dict[str, Any] = Depends(require_signed_request)) -> Dict[str, Any]:
        require_permission(identity, "read")
        return {"results": core.find_concept_neighbors(q, max(1, min(k, 50)))}

def run_frontier_causal_cycle(self,request:CycleRequest,ablate:Optional[Iterable[str]]=None)->dict[str,Any]:
        ablated=set(ablate or []); cycle_id=f'RC7-FRONTIER-{uuid.uuid4().hex[:12]}'; trace=[]; before=self.memory_count()
        source=None if 'MEMORY_READ' in ablated else self.get_resource(request.resource_id,include_text=True)
        source_status=str((source or {}).get('metadata',{}).get('status','UNKNOWN'))
        trace.append({'stage':'MEMORY','resource_id':request.resource_id,'found':source is not None,'source_status':source_status,'ablated':'MEMORY_READ' in ablated})
        plan=[str(a['id']) for a in request.actions] if 'THINKING' in ablated else self.thinking_plan(request.actions)
        plan_valid=self.thinking_plan_valid(request.actions,plan); trace.append({'stage':'THINKING','plan_ids':plan,'plan_valid':plan_valid,'ablated':'THINKING' in ablated})
        old=baseline_score(request.task.train); gap=1.0 if float(old['train_exact'])<1.0 else 0.0
        admission=self.logic_admission(source_status,ablated='LOGIC' in ablated); evidence_complete=1.0 if admission=='ALLOW' else 0.0
        trace.append({'stage':'LOGIC','admission':admission,'source_status':source_status,'evidence_complete':evidence_complete,'ablated':'LOGIC' in ablated})
        features=dict(request.features); features['evidence_complete']=evidence_complete; features['expressiveness_gap']=gap
        strategy=self.intelligence_strategy(features,ablated='INTELLIGENCE' in ablated); trace.append({'stage':'INTELLIGENCE','features':features,'strategy':strategy,'ablated':'INTELLIGENCE' in ablated})
        action={'strategy':strategy,'old_substrate_train_exact':float(old['train_exact'])}; live=None; blind=abscore=restore=0.0; digest=None
        if strategy=='EXPAND_REPRESENTATION' and plan_valid and admission=='ALLOW':
            if 'MECHANISM' in ablated:
                blind=float(baseline_score(request.task.blind)['train_exact']); action.update({'mechanism':'OLD_FIXED_PHASE_A','verdict':'NO_EXPRESSIVE_MECHANISM'})
            else:
                best,generated=self._frontier.search(request.task.train)
                if best is None:
                    action.update({'mechanism':'VALIDATED_FRONTIER_PORTFOLIO','verdict':'NO_SCHEMA','generated_candidates':generated})
                else:
                    schema=best.schema; blind=float(self._frontier.score(schema,request.task.blind).exact); abscore=float(baseline_score(request.task.blind)['train_exact']); restore=float(self._frontier.score(schema,request.task.blind).exact); digest=getattr(schema,'digest',None)
                    if best.exact==1.0 and blind==1.0 and restore==1.0 and blind>abscore:
                        live=self._frontier.execute(schema,request.task.live_input); action.update({'mechanism':'VALIDATED_FRONTIER_PORTFOLIO','schema':self._schema_dict(schema),'generated_candidates':generated,'train_exact':best.exact,'blind_exact':blind,'ablation_old_substrate':abscore,'restore_exact':restore,'verdict':'BOUNDED_EXECUTE'})
                    else: action.update({'mechanism':'VALIDATED_FRONTIER_PORTFOLIO','verdict':'WITHHOLD_VALIDATION','generated_candidates':generated})
        elif strategy=='SEEK_EVIDENCE':
            action.update({'mechanism':'MEMORY_RETRIEVAL','neighbors':[] if 'MEMORY_READ' in ablated else self.find_concept_neighbors(request.resource_query,k=3),'verdict':'EVIDENCE_REQUESTED'})
        else: action.update({'mechanism':None,'verdict':'WITHHOLD'})
        trace.append({'stage':'EXECUTION','action':action,'live_output':live,'mechanism_digest':digest,'ablated':'MECHANISM' in ablated})
        output_correct=(live==request.task.expected_live); valid=(blind==1.0 and restore==1.0 and blind>abscore); memory_id=None
        if 'LEARNING' not in ablated and output_correct and valid:
            memory_id=self.remember(cycle_id,'RC7_FRONTIER_DEVELOPMENT_OUTCOME',{'task':request.task.name,'strategy':strategy,'source':request.resource_id,'mechanism_digest':digest,'blind_score':blind,'ablation_score':abscore,'restore_score':restore,'live_output':live})
        after=self.memory_count(); closed=memory_id is not None and after==before+1
        trace.append({'stage':'LEARNING_MEMORY','memory_id':memory_id,'memory_count_before':before,'memory_count_after':after,'closed_loop':closed,'ablated':'LEARNING' in ablated})
        success=bool(source is not None and plan_valid and admission=='ALLOW' and strategy=='EXPAND_REPRESENTATION' and output_correct and valid and closed)
        result={'profile':self.PROFILE,'cycle_id':cycle_id,'cycle_success':success,'source_status':source_status,'plan_valid':plan_valid,'admission':admission,'strategy':strategy,'expressiveness_gap':gap,'old_substrate_train_exact':float(old['train_exact']),'blind_score':blind,'ablation_score':abscore,'restore_score':restore,'live_output':live,'expected_live':request.task.expected_live,'output_correct':output_correct,'learning_closed':closed,'mechanism_digest':digest,'ablated_components':sorted(ablated),'canonical_durable_mutation':False,'frontier_portfolio_active':True}
        self._record_cycle(cycle_id,request,result,trace); result['trace']=trace; return result

class CapabilityBoundaryProfile:
    def __init__(self, prior_success:float=1.0, prior_failure:float=1.0):
        self.prior_success=float(prior_success); self.prior_failure=float(prior_failure)
        self._bins=defaultdict(lambda:[0,0])
    @staticmethod
    def _bin(difficulty:float)->int:
        x=max(0.0,min(1.0,float(difficulty)))
        return min(3,int(x*4))
    def update(self, obs:CapabilityObservation):
        k=(obs.capability.upper(),self._bin(obs.difficulty))
        self._bins[k][0 if obs.success else 1]+=1
    def fit(self, observations:Iterable[CapabilityObservation]):
        for o in observations:self.update(o)
        return self
    def confidence(self, capability:str,difficulty:float)->float:
        cap=capability.upper(); b=self._bin(difficulty)
        # Borrow neighboring bins with distance weighting so unseen difficulty slices fail soft.
        succ=fail=0.0
        for j in range(4):
            s,f=self._bins.get((cap,j),(0,0)); w=1.0/(1.0+abs(j-b))
            succ+=w*s; fail+=w*f
        return (self.prior_success+succ)/(self.prior_success+self.prior_failure+succ+fail)
    def snapshot(self)->dict[str,Any]:
        rows={f'{c}:{b}':{'success':s,'failure':f} for (c,b),(s,f) in sorted(self._bins.items())}
        return {'prior_success':self.prior_success,'prior_failure':self.prior_failure,'bins':rows}

def confidence(self, capability:str,difficulty:float)->float:
        cap=capability.upper(); b=self._bin(difficulty)
        # Borrow neighboring bins with distance weighting so unseen difficulty slices fail soft.
        succ=fail=0.0
        for j in range(4):
            s,f=self._bins.get((cap,j),(0,0)); w=1.0/(1.0+abs(j-b))
            succ+=w*s; fail+=w*f
        return (self.prior_success+succ)/(self.prior_success+self.prior_failure+succ+fail)

def main():
    root = Path('/mnt/data/yado_continue')
    db = root/'yado_notion_training_development.db'
    if db.exists(): db.unlink()
    core = UnifiedCognitiveSystemV22(str(db), embedder=HashingEmbedder(128))
    try:
        resource_receipts=[]
        for s in SOURCES:
            resource_receipts.append(core.add_resource(s['resource_id'], s['text'], metadata={'provider':'notion','title':s['title'],'url':s['url'],'authority':False}, tags=['notion','external_evidence','development_history']))
        retrieval = core.find_concept_neighbors('external evidence authority quarantine rebase blind validation source binding', k=3)

        source_binding = develop(core, 'learn source provenance binding for Notion evidence', 'notion_source_binding', 'MEMORY', SOURCE_BIND_TRAIN, SOURCE_BIND_BLIND)
        admission = develop(core, 'learn admission semantics for external evidence', 'external_evidence_admission', 'LOGIC', ADMISSION_TRAIN, ADMISSION_BLIND)
        planner = develop(core, 'learn action sequence for handling external evidence', 'external_evidence_plan', 'THINKING', PLAN_TRAIN, PLAN_BLIND)

        probes={
            'source_binding': core.executive.execute_capability('notion_source_binding', {'page_url':'notion://page/LIVE','provider':'notion','title':'Live'}),
            'admission': {s:core.executive.execute_capability('external_evidence_admission', {'layer_status':s}) for s in ['QUARANTINED','REBASE_REQUIRED','STALE_REFERENCE','EXTERNAL_EVIDENCE','ACTIVE_VERIFIED','ACTIVE_REPAIRED_REVERSIBLE_OVERLAY']},
            'plan': {s:core.executive.execute_capability('external_evidence_plan', {'admission':s}) for s in ['WITHHOLD','EVIDENCE_ONLY','ALLOW']},
        }
        organs={k:asdict(v) for k,v in core.executive.organs.items() if v.revision}
        report={
            'schema':'yado.notion.training_and_development.v2',
            'notion_connection':{
                'verified':True,
                'mode':'host_mediated_external_evidence',
                'resources_registered':len(resource_receipts),
                'notion_is_authority':False,
                'retrieval':retrieval,
            },
            'development':{
                'source_binding':source_binding,
                'admission':admission,
                'planner':planner,
            },
            'live_probes':probes,
            'evolved_organs':organs,
            'boundaries':{
                'noesis_identity_imported':False,
                'noesis_durable_state_imported':False,
                'canonical_yado_durable_head_modified':False,
                'local_development_db_only':True,
                'notion_write_required_for_reasoning':False,
            },
        }
        (root/'yado_notion_training_development_report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
        print(json.dumps(report,ensure_ascii=False,indent=2))
    finally:
        core.close()
